import { useQuery } from '@tanstack/react-query';
import { api } from '../../api/client';
import type { DeliveryReport } from '../../api/types';
import { Badge, Spinner } from '../../shared/ui';

const STATUS_TONE: Record<string, 'ok' | 'warn' | 'bad'> = { verified: 'ok', unverified: 'warn', failed: 'bad' };
const STATUS_TEXT: Record<string, string> = { verified: '已验证', unverified: '未验证', failed: '失败' };

// 交付：由运行时从账本生成（不是模型写的）。未完成和未验证的放在最前面；“已验证”只表示覆盖它的检查在最终快照上通过。
// Delivery: generated by the runtime from the ledger (not by a model). What is open or unverified comes first; "verified" only means the check covering it passed on the final snapshot.
export function DeliveryPanel({ runId, live }: { runId: string; live: boolean }) {
  const q = useQuery({ queryKey: ['delivery', runId], queryFn: ({ signal }) => api<DeliveryReport>('/projects/' + runId + '/delivery', undefined, signal), refetchInterval: live ? 5000 : false });
  if (q.isLoading) return <div className="center pad"><Spinner /> 生成交付报告…</div>;
  if (q.isError || !q.data) return <p className="bad-text pad">{(q.error as Error | null)?.message ?? '读取失败'}</p>;
  const { delivery: d, markdown, inconsistencies } = q.data;
  if (d.reason) return <p className="muted pad">{d.reason}</p>;
  const verified = d.acceptance.filter((a) => a.status === 'verified').length;
  return (
    <div className="report-panel">
      <div className="row between">
        <span className="row">
          <Badge tone={d.complete ? 'ok' : 'warn'} dot>{d.complete ? 'Gate 通过 · 验收项齐全' : '未完成 / 部分验证'}</Badge>
          <span className="muted">验收项 {verified}/{d.acceptance.length} 已验证 · {d.independent_evidence.length ? '有独立证据' : '没有独立证据（检查由模型编写，请抽查关键行为）'}</span>
        </span>
        <button className="btn sm" onClick={() => void navigator.clipboard?.writeText(markdown)}>复制 DELIVERY.md</button>
      </div>
      {inconsistencies.length > 0 && <p className="bad-text">报告与账本不一致：{inconsistencies.join('；')}</p>}
      {d.open_items.length > 0 && (
        <ul className="entries">{d.open_items.map((i, n) => <li key={n}><code>{i.kind}</code><span>{i.text}</span></li>)}</ul>
      )}
      <div className="table-wrap">
        <table>
          <thead><tr><th>#</th><th>验收项</th><th>状态</th><th>证据</th></tr></thead>
          <tbody>
            {d.acceptance.map((a) => (
              <tr key={a.index}>
                <td>{a.index + 1}</td><td>{a.text}</td>
                <td><Badge tone={STATUS_TONE[a.status] ?? 'warn'}>{STATUS_TEXT[a.status] ?? a.status}</Badge></td>
                <td className="mono">{a.evidence.map((e) => `${e.operation} exit ${e.exit_code}`).join(' · ') || '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <h4>假设与决策</h4>
      <ul className="entries">{d.assumptions.map((a, n) => <li key={n}><code>{a.source}</code><span>{a.text}</span></li>)}</ul>
      <p className="muted">怎么运行：<code>{d.how_to_run}</code> · 模型调用 {d.cost.calls} 次 · 人工干预 {d.cost.human_interventions} 次</p>
    </div>
  );
}
